# -*- coding: utf-8 -*-
# (speaker, french, korean); speaker None => stage direction (not a turn)
H, L, C, B = "Hélène", "Lucien", "Chloé", "M. Bastide"
D = [
(None, "Mardi, fin avril, 7 h 50. Une camionnette blanche s'arrête devant la porte de service.", "4월 말 화요일 오전 7시 50분. 하얀 화물차가 뒷문 앞에 선다."),
(B, "Bonjour, bonjour ! Livraison Bastide, tout frais du matin !", "안녕하세요, 안녕하세요! 바스티드 납품입니다, 오늘 아침 갓 딴 걸로요!"),
(H, "Salut, Bastide. T'es en avance, aujourd'hui.", "안녕, 바스티드. 오늘은 일찍 왔네."),
(B, "Eh oui ! La route était vide, c'est rare.", "그러게요! 길이 텅 비었어요, 드문 일이죠."),
(H, "Tant mieux. Chloé, viens, je te présente monsieur Bastide.", "잘됐네. 클로에, 이리 와, 바스티드 씨를 소개할게."),
(C, "Bonjour, monsieur. Enchantée. Je suis Chloé.", "안녕하세요, 선생님. 반갑습니다. 저는 클로에예요."),
(B, "Enchanté, mademoiselle. C'est vous qui allez vérifier mes cagettes ?", "반갑습니다, 아가씨. 내 상자들을 검수하는 게 당신인가요?"),
(H, "Oui. Aujourd'hui, c'est elle qui contrôle la livraison. Moi, je regarde.", "응. 오늘은 이 애가 납품을 검수해. 나는 지켜볼게."),
(C, "Moi ? Mais je sais pas faire !", "저요? 근데 저 할 줄 모르는데요!"),
(H, "Tu vas apprendre. On commence par le bon de livraison.", "배우면 돼. 납품서부터 시작하자."),
(C, "D'accord. Qu'est-ce que je dois regarder, exactement ?", "알겠어요. 정확히 뭘 봐야 하는 거죠?"),
(H, "Le bon dit ce qu'on a commandé. Tu compares avec ce qui arrive.", "납품서에는 우리가 주문한 게 적혀 있어. 도착한 것과 비교하는 거야."),
(B, "Tenez, mademoiselle. Les légumes d'abord, la viande ensuite.", "여기요, 아가씨. 채소 먼저, 고기는 그다음이에요."),
(C, "Alors... asperges vertes, cinq kilos. Petits pois, trois kilos. Radis, dix bottes.", "그러니까... 그린 아스파라거스 5킬로, 완두콩 3킬로, 래디시 열 단."),
(B, "C'est ça. Et regardez les asperges : elles sont superbes, cette année.", "맞아요. 그리고 아스파라거스 좀 봐요, 올해 아주 훌륭해요."),
(C, "Elles sont plus grosses que la semaine dernière, non ?", "지난주보다 더 굵네요, 그렇죠?"),
(B, "Oui ! Avec la pluie de mars, elles ont poussé plus vite.", "네! 3월에 비가 와서 더 빨리 자랐어요."),
(H, "Plus grosses, oui. Mais pas forcément meilleures. Les petites sont souvent plus tendres.", "더 굵긴 하지. 하지만 꼭 더 맛있는 건 아니야. 가는 게 보통 더 부드럽거든."),
(B, "Hélène, tu me connais ! Goûte, et tu verras.", "엘렌, 나를 알잖아! 맛을 봐, 그럼 알 거야."),
(None, "Hélène casse un bout d'asperge crue et le croque.", "엘렌이 날 아스파라거스 끝을 똑 부러뜨려 베어 문다."),
(H, "Hmm. Croquante. Un peu amère au bout, mais ça va.", "음. 아삭하네. 끝이 약간 쓰지만, 괜찮아."),
(C, "On goûte cru ? Je pensais qu'on devait d'abord les cuire.", "생으로 맛을 봐요? 먼저 익혀야 하는 줄 알았어요."),
(B, "Mais non ! Une bonne asperge, ça se mange crue. Cassez le bout : ça doit craquer.", "아니에요! 좋은 아스파라거스는 생으로 먹어요. 끝을 꺾어 봐요, 똑 소리가 나야 해요."),
(C, "Ça craque ! C'est bon signe, alors ?", "똑 소리 나요! 그럼 좋은 신호죠?"),
(H, "C'est bon signe. Une asperge molle, on la refuse.", "좋은 신호야. 흐물흐물한 아스파라거스는 돌려보내."),
(C, "Et les petits pois ? Ils sont encore dans les cosses.", "그럼 완두콩은요? 아직 깍지 안에 있네요."),
(B, "Oui, en cosses. Ça se conserve mieux, mais il faut les écosser avant de cuire.", "네, 깍지째로요. 보관은 더 잘 되는데, 익히기 전에 까야 해요."),
(H, "Ça prend du temps, mais le velouté est meilleur avec des petits pois frais qu'avec du surgelé.", "시간이 걸리지만, 벨루테는 냉동보다 생 완두콩으로 만들 때 더 맛있어."),
(C, "Je peux les écosser ! J'aime bien ça, c'est relaxant.", "제가 깔게요! 저 그거 좋아해요, 마음이 편해지거든요."),
(L, "Tu diras la même chose dans une heure, quand il y en aura trois kilos !", "한 시간 뒤에 세 킬로나 쌓여 있으면 똑같이 말할지 두고 보자!"),
(None, "Lucien arrive par la ruelle, un journal sous le bras.", "뤼시앵이 신문을 옆구리에 끼고 골목으로 들어온다."),
(H, "Papa ! Il est même pas huit heures.", "아빠! 아직 여덟 시도 안 됐어요."),
(L, "J'ai senti l'odeur des asperges depuis le coin de la rue. Bonjour, Bastide !", "길모퉁이에서부터 아스파라거스 냄새가 나더라. 안녕, 바스티드!"),
(B, "Monsieur Lucien ! Toujours le nez fin, vous.", "뤼시앵 어르신! 여전히 코가 밝으시네요."),
(L, "On ne se refait pas. Alors, ces asperges, elles sont à combien ?", "사람은 안 바뀌는 법이지. 그래, 이 아스파라거스는 얼마인가?"),
(B, "Pour Hélène, huit euros cinquante le kilo.", "엘렌한테는 킬로에 8유로 50이에요."),
(H, "Huit cinquante ? La semaine dernière, c'était huit euros.", "8유로 50이요? 지난주엔 8유로였잖아요."),
(B, "Oui, mais la semaine dernière, elles étaient plus petites. Là, c'est du calibre extra.", "맞아요, 근데 지난주엔 더 작았잖아요. 이건 특대 크기예요."),
(H, "Bastide... Huit euros, pas plus. Sinon je prends un kilo de moins.", "바스티드... 8유로, 그 이상은 안 돼요. 아니면 1킬로 덜 살게요."),
(B, "Ah là là, elle est dure en affaires, la patronne !", "아이고, 사장님 장사 수완 참 매섭네!"),
(L, "Elle tient ça de sa mère. Marthe aussi marchandait, mais toujours avec le sourire.", "제 엄마를 닮았지. 마르트도 흥정을 했는데, 늘 웃으면서 했어."),
(B, "C'est vrai. Bon, d'accord : huit euros. Mais c'est bien parce que c'est vous.", "맞아요. 좋아요, 알았어요, 8유로. 하지만 정말 당신들이라서 해 드리는 거예요."),
(H, "Merci. Chloé, on pèse. Pose la première cagette sur la balance.", "고마워요. 클로에, 무게를 달자. 첫 상자를 저울에 올려."),
(C, "La balance indique cinq kilos quatre cents. C'est bon, non ? Sur le bon, c'est écrit cinq kilos.", "저울에 5킬로 400이 나와요. 괜찮죠? 납품서엔 5킬로라고 적혀 있어요."),
(H, "Attends. Il faut enlever le poids de la cagette. C'est la tare.", "잠깐. 상자 무게를 빼야 해. 그걸 '타르'라고 해."),
(C, "La tare ? C'est quoi, ça ?", "타르요? 그게 뭐예요?"),
(H, "Le poids du récipient vide. Ici, une cagette fait six cents grammes.", "빈 용기의 무게야. 여기서는 상자 하나가 600그램이지."),
(C, "Donc cinq kilos quatre cents moins six cents grammes... ça fait quatre kilos huit cents.", "그러니까 5킬로 400에서 600그램을 빼면... 4킬로 800이네요."),
(B, "Deux cents grammes de moins, c'est vrai. Je vous les rajoute tout de suite.", "200그램 모자라네요, 맞아요. 바로 더 채워 드릴게요."),
(L, "Les bons comptes font les bons amis, mon vieux Bastide.", "정확한 셈이 좋은 친구를 만드는 법이지, 바스티드 영감."),
(B, "Je n'ai jamais dit le contraire, monsieur Lucien !", "저는 한 번도 그 반대를 말한 적이 없어요, 뤼시앵 어르신!"),
(C, "Je note ça dans mon carnet : « la tare ». Ça s'écrit comment ?", "수첩에 적어 둘게요. 'la tare'. 철자가 어떻게 되죠?"),
(H, "T, A, R, E. Comme le défaut, mais en cuisine, c'est juste un poids.", "T, A, R, E. 결함이라는 뜻과 철자가 같지만, 주방에서는 그냥 무게일 뿐이야."),
(B, "Passons à la viande. J'ai six kilos d'épaule de veau pour votre blanquette.", "고기로 넘어갑시다. 블랑케트용 송아지 어깨살 6킬로를 가져왔어요."),
(H, "Montre. Hmm, la couleur est belle : rose pâle.", "보여 줘요. 음, 색이 곱네. 연한 분홍빛이야."),
(C, "Pourquoi rose pâle ? Je croyais que la viande devait être rouge.", "왜 연한 분홍이에요? 고기는 빨개야 하는 줄 알았는데요."),
(H, "Le veau est plus clair que le bœuf. S'il est trop rouge, il est trop vieux.", "송아지는 소고기보다 색이 연해. 너무 붉으면 너무 오래된 거야."),
(H, "Touche-le. Il doit être ferme et sec, pas collant.", "만져 봐. 단단하고 말라 있어야지, 끈적이면 안 돼."),
(C, "C'est frais et sec. Et ça ne sent rien. C'est bien ?", "차갑고 보송해요. 냄새도 안 나요. 좋은 거죠?"),
(H, "Très bien. Une viande fraîche sent presque rien. Monsieur Bastide, c'est combien le kilo ?", "아주 좋아. 신선한 고기는 거의 냄새가 안 나. 바스티드 씨, 킬로에 얼마죠?"),
(B, "Quatorze euros. C'est un peu plus cher qu'avant, mais le prix a augmenté partout.", "14유로예요. 예전보다 조금 비싸지만, 가격이 어디서나 올랐어요."),
(H, "Quatorze... Chez ton concurrent, c'est combien ?", "14... 경쟁 업체는 얼마야?"),
(B, "Chez Dubreuil ? Seize euros, et sa viande est moins bonne que la mienne. Je le dis sans méchanceté.", "뒤브레유네요? 16유로인데, 고기는 제 것보다 못해요. 악의 없이 하는 말이에요."),
(L, "Sans méchanceté, mais avec beaucoup de plaisir !", "악의는 없고, 대신 즐거움은 한가득이로군!"),
(B, "Ha ! Monsieur Lucien me connaît trop bien.", "하! 뤼시앵 어르신은 저를 너무 잘 아세요."),
(H, "D'accord pour quatorze. Mais je veux voir les œufs aussi.", "14유로 좋아요. 그런데 달걀도 보고 싶어요."),
(B, "Trois plateaux de trente, de mes poules. Elles pondent mieux que jamais.", "30개들이 세 판이에요, 우리 닭들이 낳은 거죠. 이렇게 잘 낳은 적이 없어요."),
(C, "Comment on sait qu'un œuf est frais ?", "달걀이 신선한지 어떻게 알아요?"),
(H, "On en casse un. Vas-y, casse celui-là dans l'assiette.", "하나 깨 보는 거야. 해 봐, 이걸 접시에 깨 봐."),
(None, "Chloé casse l'œuf avec précaution. Le jaune reste bien bombé.", "클로에가 조심스레 달걀을 깬다. 노른자가 동그랗게 봉긋하다."),
(C, "Oh, il est tout rond, le jaune ! Et le blanc ne coule pas.", "와, 노른자가 완전 동그래요! 흰자도 퍼지지 않고요."),
(H, "C'est ça. Un œuf frais, le jaune est haut. Un vieil œuf, tout s'étale.", "그거야. 신선한 달걀은 노른자가 솟아 있고, 오래된 건 다 퍼져."),
(C, "Je comprends mieux. C'est vraiment plus facile à voir qu'à expliquer.", "이제 좀 알겠어요. 설명하는 것보다 눈으로 보는 게 훨씬 쉽네요."),
(B, "Et maintenant, ma petite fierté : les carottes de printemps. Un peu tordues, mais délicieuses.", "그리고 이제 제 작은 자랑거리, 봄 당근입니다. 좀 휘었지만 맛있어요."),
(C, "Elles sont bizarres ! Celle-ci ressemble à une main.", "이상하게 생겼어요! 이건 손처럼 생겼네요."),
(H, "Elles sont moins jolies que les carottes du supermarché, mais bien plus sucrées.", "마트 당근보다 예쁘진 않지만, 훨씬 더 달아."),
(L, "L'habit ne fait pas le moine, ma petite. Ça vaut pour les carottes aussi.", "옷이 수도승을 만드는 건 아니란다, 아가. 당근에도 해당되는 말이야."),
(C, "Alors on les prend ? Elles feront de beaux légumes glacés.", "그럼 받을까요? 글라세 채소로 근사하겠어요."),
(H, "Oui. Cinq kilos. Elles sont à combien, Bastide ?", "응. 5킬로. 얼마예요, 바스티드?"),
(B, "Deux euros cinquante le kilo. Là, personne ne peut dire que je suis cher.", "킬로에 2유로 50입니다. 이건 누구도 내가 비싸다고 못 하죠."),
(H, "C'est vrai. Pour les carottes, tu es le moins cher de la région.", "맞아. 당근은 이 지역에서 당신이 제일 싸지."),
(C, "Je fais le total ? J'ai la calculatrice du téléphone.", "합계를 낼까요? 휴대폰 계산기가 있어요."),
(H, "Fais-le à la main d'abord. Le téléphone, tu vérifies après.", "먼저 손으로 해. 휴대폰은 나중에 확인할 때 써."),
(C, "Asperges, quatre kilos huit cents plus deux cents, ça fait cinq kilos à huit euros : quarante euros.", "아스파라거스는 4킬로 800에 200을 더해서 5킬로, 8유로니까 40유로예요."),
(C, "Petits pois, trois kilos à quatre euros : douze euros. Carottes, cinq kilos à deux cinquante : douze cinquante.", "완두콩 3킬로에 4유로니까 12유로. 당근 5킬로에 2유로 50이니까 12유로 50."),
(H, "Bien. Continue. Le veau, et les œufs ?", "좋아. 계속해. 송아지고기와 달걀은?"),
(C, "Veau, six kilos à quatorze : quatre-vingt-quatre euros. Les œufs... je ne connais pas le prix.", "송아지고기 6킬로에 14유로니까 84유로. 달걀은... 가격을 몰라요."),
(B, "Neuf euros le plateau. Trois plateaux, vingt-sept euros.", "한 판에 9유로예요. 세 판이니까 27유로."),
(C, "Quarante, douze, douze cinquante, quatre-vingt-quatre, vingt-sept... Je me perds un peu.", "40, 12, 12유로 50, 84, 27... 좀 헷갈려요."),
(L, "Respire, ma grande. Les bons comptes, on les fait doucement.", "숨을 쉬렴, 우리 아가. 정확한 셈은 천천히 하는 거야."),
(C, "Alors... cent soixante-quinze euros cinquante au total.", "그러면... 합계는 175유로 50이에요."),
(B, "Sur ma facture, j'ai cent soixante-quinze cinquante. Bravo, mademoiselle !", "제 청구서에도 175유로 50이에요. 잘했어요, 아가씨!"),
(H, "Voilà. Pas d'erreur. Signe en bas du bon, Chloé, là où c'est marqué « reçu par ».", "자. 오류 없네. 클로에, 납품서 아래 '수령인' 적힌 곳에 서명해."),
(C, "Je signe de mon vrai nom ? Je suis un peu stressée.", "진짜 이름으로 서명하나요? 조금 떨리네요."),
(H, "Oui. Et tu écris la date. Si un jour il y a un problème, ce papier est notre preuve.", "응. 그리고 날짜도 써. 나중에 문제가 생기면 이 종이가 증거가 돼."),
(B, "Allez, une botte de radis pour la jeune fille. Cadeau de la maison Bastide.", "자, 아가씨에게 래디시 한 단 드릴게요. 바스티드 농장의 선물이에요."),
(C, "Oh, merci, monsieur ! C'est gentil, mais je ne peux pas accepter.", "어머, 감사합니다! 친절하시네요, 하지만 받을 수는 없어요."),
(H, "Tu peux. C'est pour tout le monde au repas du personnel. Les radis au beurre, c'est ce qu'on mange ce midi.", "받아도 돼. 직원 식사용으로 다 같이 먹는 거야. 오늘 점심은 버터 곁들인 래디시지."),
(L, "Radis, beurre, pain frais, sel. Un vrai repas de roi.", "래디시, 버터, 신선한 빵, 소금. 진짜 왕의 식사지."),
(B, "Vous voyez ? Ça met du beurre dans les épinards, un client comme Hélène !", "보세요? 엘렌 같은 손님이 있으면 형편이 풍족해진다니까요!"),
(L, "Doucement avec les épinards, Bastide. Pour l'instant, on parle surtout d'asperges.", "시금치 얘기는 천천히 하게, 바스티드. 지금은 주로 아스파라거스 얘기야."),
(B, "Ha ha ! Allez, je file. À jeudi, mademoiselle Chloé ?", "하하! 자, 저는 갑니다. 목요일에 봐요, 클로에 양?"),
(C, "À jeudi, monsieur Bastide. Merci pour la leçon !", "목요일에 봬요, 바스티드 선생님. 수업 감사해요!"),
(C, "Au fait, les asperges vertes, on les épluche ?", "참, 그린 아스파라거스는 껍질을 벗기나요?"),
(H, "Juste le bas de la tige, avec l'économe. Le reste, non.", "줄기 아랫부분만 필러로 벗겨. 나머지는 아니야."),
(C, "Et on les cuit combien de temps ?", "그리고 얼마나 익혀요?"),
(H, "Cinq ou six minutes à l'eau bouillante salée. Elles doivent rester croquantes.", "소금 넣은 끓는 물에 5~6분. 아삭함이 남아 있어야 해."),
(C, "Donc plus elles sont fines, moins on les cuit ?", "그럼 가늘수록 덜 익히는 거네요?"),
(H, "Exactement. Tu as tout compris. Bon, cagettes à l'intérieur.", "정확해. 다 이해했네. 자, 상자는 안으로."),
(H, "Les asperges au frigo. Chloé, tu t'en occupes ?", "아스파라거스는 냉장고로. 클로에, 맡아 줄래?"),
(C, "Tout de suite. Les asperges en haut, la viande en bas, c'est ça ?", "바로 할게요. 아스파라거스는 위, 고기는 아래, 맞죠?"),
(H, "Oui. La viande en bas, toujours. Si ça goutte, ça ne tombe pas sur les légumes.", "응. 고기는 항상 아래야. 핏물이 떨어져도 채소 위에는 안 떨어지게."),
(C, "Compris. Et les carottes ? Je les mets où ?", "알겠어요. 그럼 당근은요? 어디에 두죠?"),
(L, "À la cave, au frais, dans du sable si tu veux bien faire. Mais pour deux jours, le frigo suffit.", "제대로 하려면 지하 저장고 서늘한 곳에 모래 속에 두고. 이틀이면 냉장고로 충분하다."),
(H, "Papa, arrête de faire le chef dans ma cuisine.", "아빠, 제 주방에서 그만 대장 노릇 하세요."),
(L, "Je suis juste venu boire un café et donner un conseil.", "나는 커피 한 잔 마시고 조언 하나 하러 왔을 뿐이다."),
(H, "Le café est sur le comptoir. Le conseil, tu le gardes pour demain.", "커피는 카운터에 있어요. 조언은 내일로 아껴 두세요."),
(L, "Demain, il y aura de nouveaux légumes, donc de nouveaux conseils. C'est logique.", "내일은 새 채소가 올 테니 새 조언도 있겠지. 논리적이잖니."),
(C, "Chef, demain, c'est moi qui contrôle la livraison toute seule ?", "셰프, 내일은 제가 혼자 납품을 검수하나요?"),
(H, "Pas demain, jeudi. Avec le bon, la balance et ta tête. Tu as tout ce qu'il faut.", "내일 말고 목요일에. 납품서와 저울, 그리고 네 머리. 필요한 건 다 있어."),
(C, "D'accord. Mais si je me trompe dans les prix ?", "알겠어요. 근데 가격을 틀리면요?"),
(H, "Tu recommences. Une erreur de calcul, ça se rattrape. Une cagette pourrie acceptée, non.", "다시 하면 돼. 계산 실수는 만회할 수 있어. 썩은 상자를 받아 버린 건 안 돼."),
(C, "J'ai compris : on regarde, on touche, on pèse, on compare.", "이해했어요. 보고, 만지고, 달고, 비교한다."),
(H, "Voilà. Et on goûte, quand c'est possible. Allez, au boulot, il est huit heures vingt.", "그래. 가능하면 맛도 보고. 자, 일하러 가자, 여덟 시 이십 분이야."),
]

